/*
 * ═══════════════════════════════════════════════════════════════════════════
 *  泰拉瑞亚 · 游戏内修改器菜单（Android 系统 UI 版）
 * ═══════════════════════════════════════════════════════════════════════════
 *  不用 JsHook 的任何图形 API：Frida 的 Java 桥 → `Activity.addContentView()`
 *  把一块原生 View（LinearLayout / Button / Switch / SeekBar / ScrollView）
 *  挂进 `com.unity3d.player.UnityPlayerActivity` 自己的窗口里。
 *
 *  由此得到：① 触摸不穿透（事件走标准 View 分发，面板吃掉的触摸游戏收不到）
 *           ② 随游戏进程存在，退出游戏即消失，不留关不掉的悬浮图标
 *           ③ 只用公开框架 API，不依赖 JsHook 守护进程
 *
 *  功能：角色（无敌 / 满配 / 回血 / 清减益 / 各类持续开关）
 *        武器（**按手持武器的种类自适应显示**：枪械才出现「无子弹发射」）
 *        世界时间（滑动改时间 + 锁定昼夜）
 *        添加物品（滑动/按钮选 ID + 按数量塞进背包空槽）
 *
 *  用法（容器里）：
 *      cd "/sdcard/Download/DSHA/泰拉瑞亚项目/控制面板"
 *      python3 jshook.py exec --file 系统菜单.js --wait 2
 *
 *  收起：点标题栏的 ▾ 收成一小块 chip（≡ 修改器），**收起后按住 chip 也能拖动**。
 *  **没有关闭按钮**：面板属于游戏进程，退出游戏它自然就关闭了，不需要手动关。
 *  程序化清理：`globalThis.TERRARIA_SYS_MENU.close()`；重发本脚本会自动先移除旧面板。
 *
 *  改界面/加功能：见文件末尾的 `ACT`（动作实现）与 `SPEC`（界面结构）。
 * ═══════════════════════════════════════════════════════════════════════════
 */
var CFG = {
  title: '泰拉瑞亚修改器',
  marker: 'dsha_terraria_menu_v1',  // 写在 contentDescription 上，用于清掉上一次残留
  host: 'content',                  // content = addContentView（首选）；panel = WindowManager 子窗口（备用）
  widthDp: 250,                     // 面板宽度（dp）：顶部 6 个标签 + 开关两列排布需要更宽一点
  heightRatio: 0.60,                // 滚动区高度 = 屏幕短边 * 该比例
  startXDp: 12,
  startYDp: 36,
  tickMs: 50,                       // 后台心跳：锁时间 / 补弹药
  pollMs: 350,                      // 手持武器种类轮询
  selfTest: false,                  // true = 挂载后自动跑一遍自检并写日志（调试用）
  prof: false,                      // true = 打印界面构建/列表计算的耗时（排查卡顿用，运行时可改：TERRARIA_SYS_MENU.cfg.prof = true）
  prewarm: true,                    // true = 挂载后空闲时预建物品面板（首次打开不再等 ~150ms 构建）
  logPrefix: '[系统菜单]'
};
